<template><div class="editorial-products min-h-screen bg-[#fffaf7] px-4 py-6 text-slate-900 sm:py-10"><div class="mx-auto max-w-6xl"><div class="mb-7 border-b border-rose-200 pb-5 sm:mb-10 sm:pb-6"><p class="text-xs font-bold uppercase tracking-[.2em] text-rose-700">02 / {{ t('nav.products') }}</p><h1 class="mt-2 text-3xl font-black sm:text-4xl">{{ t('nav.products') }}</h1></div><div v-if="loading" class="py-16 text-center">...</div><TemplateProductCollection v-else :products="products" :mode="templateMode" grid-class="grid grid-cols-1 gap-4 sm:grid-cols-2" @click="go" @quick-buy="quickBuy"/><ProductQuickBuy v-if="selected" :product="selected" :visible="quickVisible" @update:visible="quickVisible = $event" /></div></div></template>
<script setup lang="ts">import { computed, onMounted, onUnmounted, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRouter } from 'vue-router'; import { useProductList } from '../../composables/useProductList'; import { useAppStore } from '../../stores/app'; import TemplateProductCollection from '../components/TemplateProductCollection.vue'; import ProductQuickBuy from '../../components/ProductQuickBuy.vue'; const {t}=useI18n(); const router=useRouter(); const app=useAppStore(); const {loading,products,initialize,cleanup}=useProductList({pageSize:12,homeRouteName:'products'}); const selected=ref<any>(null); const quickVisible=ref(false); const templateMode=computed<'card'|'list'>(()=>app.config?.template_mode==='list'?'list':'card'); const go=(s:string)=>router.push(`/products/${s}`); const quickBuy=(p:any)=>{selected.value=p;quickVisible.value=true}; onMounted(async()=>{await app.loadConfig();await initialize()}); onUnmounted(cleanup)</script>
